      it(`rejects a quantity of ${label} with TypeError`, () => {
        assert.throws(() => cart.addItem('apple', 1, value), {
          name: 'TypeError',
          message: /quantity must be a finite number/,
        });
        assert.deepEqual(cart.items, []);
      });
