        message: 'Cannot remove "durian": item is not in the cart',
      });
      assert.deepEqual(cart.items, before);
    });

    it('removes the first and last items correctly', () => {
      cart.removeItem('apple');
      cart.removeItem('cherry');
      assert.deepEqual(cart.items, [{ name: 'banana', price: 2, quantity: 1 }]);
    });

    it('removes the whole line item regardless of its quantity', () => {
      cart.addItem('apple', 1, 9);
      cart.removeItem('apple');
      assert.equal(cart.items.some(i => i.name === 'apple'), false);
    });

    it('throws when removing the same item twice', () => {
      cart.removeItem('apple');
      assert.throws(() => cart.removeItem('apple'), /item is not in the cart/);
    });

