        name: 'RangeError',
        message: 'discount percent must be between 0 and 100, received 150',
      });
      assert.equal(cart.discount, 0);
    });

    it('bug 5: rejects a negative discount with RangeError', () => {
      assert.throws(() => cart.applyDiscount(-10), RangeError);
      assert.equal(cart.discount, 0);
    });

    it('bug 5: rejects values just outside the range (100.01 and -0.01)', () => {
      assert.throws(() => cart.applyDiscount(100.01), RangeError);
      assert.throws(() => cart.applyDiscount(-0.01), RangeError);
    });

    it('bug 5: a rejected discount keeps the previous valid discount', () => {
      cart.addItem('jacket', 100, 1);
      cart.applyDiscount(20);
      assert.throws(() => cart.applyDiscount(101), RangeError);
      assert.equal(cart.discount, 20);
      assert.equal(cart.getTotal(), 80);
    });

    for (const [label, value] of [['a numeric string', '10'], ['null', null], ['undefined', undefined], ['NaN', Number.NaN], ['Infinity', Infinity]]) {
      it(`bug 5: rejects a discount of ${label} with TypeError`, () => {
