'use strict';

const MIN_DISCOUNT_PERCENT = 0;
const MAX_DISCOUNT_PERCENT = 100;

// Formats a rejected value for an error message without throwing on symbols,
// null-prototype objects, or other values that String() cannot convert.
function describe(value) {
  if (typeof value === 'string') return JSON.stringify(value);
  if (typeof value === 'number') return String(value);
  return value === null ? 'null' : typeof value;
}

function assertItemName(name) {
  if (typeof name !== 'string' || name.trim() === '') {
    throw new TypeError(`name must be a non-empty string, received ${describe(name)}`);
  }
}

function assertFiniteNumber(value, label) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`${label} must be a finite number, received ${describe(value)}`);
  }
}

function assertQuantity(quantity) {
  assertFiniteNumber(quantity, 'quantity');
  if (!Number.isSafeInteger(quantity) || quantity < 1) {
    throw new RangeError(`quantity must be a positive integer, received ${quantity}`);
  }
}

/**
 * In-memory shopping cart. Every method validates its input before touching
 * state, so a call that throws leaves the cart exactly as it was.
 */
class ShoppingCart {
  constructor() {
    this.items = [];
    this.discount = 0;
  }

  /**
   * Adds a line item, or adds to the quantity of the existing item with the
   * same name. When merging, the existing unit price is kept.
   *
   * @param {string} name Non-empty item name. Matching is exact and case-sensitive.
   * @param {number} price Unit price; finite and >= 0 (0 allows free items).
   * @param {number} quantity Positive safe integer.
   * @throws {TypeError} If name is not a non-empty string, or price/quantity is not a finite number.
   * @throws {RangeError} If price is negative, or quantity is not a positive safe integer
   *   (including when merging would push the stored quantity past Number.MAX_SAFE_INTEGER).
   */
  addItem(name, price, quantity) {
    assertItemName(name);
    assertFiniteNumber(price, 'price');
    if (price < 0) {
      throw new RangeError(`price must be >= 0, received ${price}`);
    }
    assertQuantity(quantity);

    const existing = this.items.find(i => i.name === name);
    if (existing) {
      const merged = existing.quantity + quantity;
      if (!Number.isSafeInteger(merged)) {
        throw new RangeError(`quantity for ${JSON.stringify(name)} would exceed ${Number.MAX_SAFE_INTEGER}`);
      }
      existing.quantity = merged;
    } else {
      this.items.push({ name, price, quantity });
    }
  }

  /**
   * Removes the line item with the given name.
   *
   * @param {string} name Name of an item currently in the cart.
   * @throws {TypeError} If name is not a non-empty string.
   * @throws {Error} If no item with that name is in the cart.
   */
  removeItem(name) {
    assertItemName(name);
    const remaining = this.items.filter(i => i.name !== name);
    if (remaining.length === this.items.length) {
      throw new Error(`Cannot remove ${JSON.stringify(name)}: item is not in the cart`);
    }
    this.items = remaining;
  }

  /**
   * Returns the sum of price * quantity across all items, reduced by the
   * current discount. The result is not rounded; formatting to a currency's
   * minor unit is left to the caller.
   *
   * @returns {number} Discounted total; 0 for an empty cart.
   */
  getTotal() {
    let total = 0;
    for (const item of this.items) {
      total += item.price * item.quantity;
    }
    return total - (total * this.discount / 100);
  }

  /**
   * Sets the cart-wide discount. Replaces any earlier discount rather than
   * stacking with it; pass 0 to clear it.
   *
   * @param {number} percent Discount percentage from 0 to 100 inclusive; fractions allowed.
   * @throws {TypeError} If percent is not a finite number.
   * @throws {RangeError} If percent is outside 0-100.
   */
  applyDiscount(percent) {
    assertFiniteNumber(percent, 'discount percent');
    if (percent < MIN_DISCOUNT_PERCENT || percent > MAX_DISCOUNT_PERCENT) {
      throw new RangeError(
        `discount percent must be between ${MIN_DISCOUNT_PERCENT} and ${MAX_DISCOUNT_PERCENT}, received ${percent}`
      );
    }
    this.discount = percent;
  }

  /**
   * @returns {number} Number of distinct line items, not the sum of their quantities.
   */
  getItemCount() {
    return this.items.length;
  }
}

module.exports = ShoppingCart;

