'use strict';

const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const ShoppingCart = require('../src/cart');

describe('ShoppingCart', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('constructor', () => {
    it('starts with no items and no discount', () => {
      assert.deepEqual(cart.items, []);
      assert.equal(cart.discount, 0);
      assert.equal(cart.getItemCount(), 0);
    });
  });

  describe('addItem', () => {
    it('adds a new item with its name, price, and quantity', () => {
      cart.addItem('apple', 1.5, 4);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 4 }]);
    });

    it('merges quantity into the existing line item for the same name', () => {
      cart.addItem('apple', 2, 1);
      cart.addItem('apple', 2, 3);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 2, quantity: 4 }]);
    });

    it('keeps the original unit price when merging a repeat add', () => {
      cart.addItem('apple', 2, 1);
      cart.addItem('apple', 99, 1);
      assert.equal(cart.items[0].price, 2);
    });

    it('treats item names as case-sensitive', () => {
      cart.addItem('Apple', 1, 1);
      cart.addItem('apple', 1, 1);
      assert.equal(cart.getItemCount(), 2);
    });

    it('accepts a price of 0 for free items', () => {
      cart.addItem('sticker', 0, 2);
      assert.equal(cart.getTotal(), 0);
      assert.equal(cart.getItemCount(), 1);
    });

    it('accepts a quantity of 1 (the smallest valid quantity)', () => {
      cart.addItem('pen', 3, 1);
      assert.equal(cart.items[0].quantity, 1);
    });

    // Bug 1 regressions: the original accepted any price and quantity.
    it('bug 1: rejects a negative price with RangeError and leaves the cart empty', () => {
      assert.throws(() => cart.addItem('apple', -1, 1), {
        name: 'RangeError',
        message: /price must be >= 0, received -1/,
      });
      assert.deepEqual(cart.items, []);
    });

    it('bug 1: rejects a negative quantity with RangeError and leaves the cart empty', () => {
      assert.throws(() => cart.addItem('apple', 1, -2), {
        name: 'RangeError',
        message: /quantity must be a positive integer, received -2/,
      });
      assert.deepEqual(cart.items, []);
    });

    it('bug 1: rejects a negative quantity that would shrink an existing line item', () => {
      cart.addItem('apple', 1, 5);
      assert.throws(() => cart.addItem('apple', 1, -3), RangeError);
      assert.equal(cart.items[0].quantity, 5);
    });

    it('rejects a quantity of 0', () => {
      assert.throws(() => cart.addItem('apple', 1, 0), RangeError);
      assert.deepEqual(cart.items, []);
    });

    it('rejects a fractional quantity', () => {
      assert.throws(() => cart.addItem('apple', 1, 1.5), RangeError);
    });

    const nonNumbers = [
      ['a numeric string', '5'],
      ['null', null],
      ['undefined', undefined],
      ['NaN', Number.NaN],
      ['Infinity', Infinity],
      ['-Infinity', -Infinity],
    ];

    for (const [label, value] of nonNumbers) {
      it(`rejects a price of ${label} with TypeError`, () => {
        assert.throws(() => cart.addItem('apple', value, 1), {
          name: 'TypeError',
          message: /price must be a finite number/,
        });
        assert.deepEqual(cart.items, []);
      });

      it(`rejects a quantity of ${label} with TypeError`, () => {
        assert.throws(() => cart.addItem('apple', 1, value), {
          name: 'TypeError',
          message: /quantity must be a finite number/,
        });
        assert.deepEqual(cart.items, []);
      });
    }

    it('rejects a missing quantity argument', () => {
      assert.throws(() => cart.addItem('apple', 1), TypeError);
    });

    for (const [label, value] of [['an empty string', ''], ['a number', 42], ['null', null], ['undefined', undefined]]) {
      it(`rejects a name that is ${label} with TypeError`, () => {
        assert.throws(() => cart.addItem(value, 1, 1), {
          name: 'TypeError',
          message: /name must be a non-empty string/,
        });
        assert.deepEqual(cart.items, []);
      });
    }
  });

  describe('removeItem', () => {
    beforeEach(() => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);
      cart.addItem('cherry', 3, 1);
    });

    // Bug 2 regressions: `i.name = name` assigned instead of comparing, so the
    // filter kept every item and renamed each one to the removed name.
    it('bug 2: removes only the named item and leaves the other names untouched', () => {
      cart.removeItem('banana');
      assert.deepEqual(
        cart.items.map(i => i.name),
        ['apple', 'cherry']
      );
    });

    it('bug 2: throws when the item is not in the cart and leaves the cart unchanged', () => {
      const before = structuredClone(cart.items);
      assert.throws(() => cart.removeItem('durian'), {
        name: 'Error',
        message: 'Cannot remove "durian": item is not in the cart',
      });
      assert.deepEqual(cart.items, before);
    });

    it('removes the first and last items correctly', () => {
      cart.removeItem('apple');
      cart.removeItem('cherry');
      assert.deepEqual(cart.items, [{ name: 'banana', price: 2, quantity: 1 }]);
    });

    it('removes the whole line item regardless of its quantity', () => {
      cart.addItem('apple', 1, 9);
      cart.removeItem('apple');
      assert.equal(cart.items.some(i => i.name === 'apple'), false);
    });

    it('throws when removing the same item twice', () => {
      cart.removeItem('apple');
      assert.throws(() => cart.removeItem('apple'), /item is not in the cart/);
    });

    it('throws when removing from an empty cart', () => {
      const empty = new ShoppingCart();
      assert.throws(() => empty.removeItem('apple'), /item is not in the cart/);
    });

    it('rejects a non-string or empty name with TypeError', () => {
      assert.throws(() => cart.removeItem(undefined), TypeError);
      assert.throws(() => cart.removeItem(''), TypeError);
      assert.throws(() => cart.removeItem(7), TypeError);
      assert.equal(cart.getItemCount(), 3);
    });

    it('allows an item to be added again after removal', () => {
      cart.removeItem('apple');
      cart.addItem('apple', 5, 2);
      assert.deepEqual(cart.items.at(-1), { name: 'apple', price: 5, quantity: 2 });
    });
  });

  describe('getTotal', () => {
    // Bug 3 regressions: `i <= this.items.length` read one past the end and
    // threw a TypeError on every call.
    it('bug 3: returns 0 for an empty cart instead of throwing', () => {
      assert.equal(cart.getTotal(), 0);
    });

    it('bug 3: returns the total for a single item without reading past the end', () => {
      cart.addItem('apple', 4, 1);
      assert.equal(cart.getTotal(), 4);
    });

    it('bug 3: sums every item, including the last one', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 10, 1);
      cart.addItem('cherry', 100, 1);
      assert.equal(cart.getTotal(), 111);
    });

    it('multiplies each unit price by its quantity', () => {
      cart.addItem('apple', 2, 3);
      cart.addItem('banana', 5, 4);
      assert.equal(cart.getTotal(), 26);
    });

    it('includes quantity added by merging repeat adds', () => {
      cart.addItem('apple', 2, 1);
      cart.addItem('apple', 2, 2);
      assert.equal(cart.getTotal(), 6);
    });

    it('drops removed items from the total', () => {
      cart.addItem('apple', 2, 1);
      cart.addItem('banana', 5, 1);
      cart.removeItem('banana');
      assert.equal(cart.getTotal(), 2);
    });

    // Bug 4 regressions: the discount was added to the total instead of subtracted.
    it('bug 4: subtracts a 10% discount (100 -> 90, not 110)', () => {
      cart.addItem('jacket', 100, 1);
      cart.applyDiscount(10);
      assert.equal(cart.getTotal(), 90);
    });

    it('bug 4: a 100% discount makes the total 0', () => {
      cart.addItem('jacket', 80, 2);
      cart.applyDiscount(100);
      assert.equal(cart.getTotal(), 0);
    });

    it('bug 4: a discounted total never exceeds the undiscounted total', () => {
      cart.addItem('jacket', 40, 3);
      const undiscounted = cart.getTotal();
      cart.applyDiscount(25);
      assert.equal(cart.getTotal(), 90);
      assert.ok(cart.getTotal() < undiscounted);
    });

    it('a 0% discount leaves the total unchanged', () => {
      cart.addItem('jacket', 50, 1);
      cart.applyDiscount(0);
      assert.equal(cart.getTotal(), 50);
    });

    it('applies a discount to an empty cart without error', () => {
      cart.applyDiscount(50);
      assert.equal(cart.getTotal(), 0);
    });
  });

  describe('applyDiscount', () => {
    it('stores the discount percentage', () => {
      cart.applyDiscount(15);
      assert.equal(cart.discount, 15);
    });

    it('accepts the inclusive boundaries 0 and 100', () => {
      cart.applyDiscount(0);
      assert.equal(cart.discount, 0);
      cart.applyDiscount(100);
      assert.equal(cart.discount, 100);
    });

    it('accepts a fractional percentage', () => {
      cart.addItem('jacket', 200, 1);
      cart.applyDiscount(12.5);
      assert.equal(cart.getTotal(), 175);
    });

    it('replaces the previous discount instead of stacking', () => {
      cart.addItem('jacket', 100, 1);
      cart.applyDiscount(10);
      cart.applyDiscount(20);
      assert.equal(cart.getTotal(), 80);
    });

    it('clears the discount when set back to 0', () => {
      cart.addItem('jacket', 100, 1);
      cart.applyDiscount(30);
      cart.applyDiscount(0);
      assert.equal(cart.getTotal(), 100);
    });

    // Bug 5 regressions: the original stored any value, so a 150% discount
    // produced a negative total and -10% silently raised the price.
    it('bug 5: rejects a discount above 100 with RangeError', () => {
      assert.throws(() => cart.applyDiscount(150), {
        name: 'RangeError',
        message: 'discount percent must be between 0 and 100, received 150',
      });
      assert.equal(cart.discount, 0);
    });

    it('bug 5: rejects a negative discount with RangeError', () => {
      assert.throws(() => cart.applyDiscount(-10), RangeError);
      assert.equal(cart.discount, 0);
    });

    it('bug 5: rejects values just outside the range (100.01 and -0.01)', () => {
      assert.throws(() => cart.applyDiscount(100.01), RangeError);
      assert.throws(() => cart.applyDiscount(-0.01), RangeError);
    });

    it('bug 5: a rejected discount keeps the previous valid discount', () => {
      cart.addItem('jacket', 100, 1);
      cart.applyDiscount(20);
      assert.throws(() => cart.applyDiscount(101), RangeError);
      assert.equal(cart.discount, 20);
      assert.equal(cart.getTotal(), 80);
    });

    for (const [label, value] of [['a numeric string', '10'], ['null', null], ['undefined', undefined], ['NaN', Number.NaN], ['Infinity', Infinity]]) {
      it(`bug 5: rejects a discount of ${label} with TypeError`, () => {
        assert.throws(() => cart.applyDiscount(value), {
          name: 'TypeError',
          message: /discount percent must be a finite number/,
        });
        assert.equal(cart.discount, 0);
      });
    }
  });

  describe('getItemCount', () => {
    it('returns 0 for an empty cart', () => {
      assert.equal(cart.getItemCount(), 0);
    });

    it('counts distinct line items, not total quantity', () => {
      cart.addItem('apple', 1, 5);
      cart.addItem('banana', 1, 3);
      cart.addItem('apple', 1, 2);
      assert.equal(cart.getItemCount(), 2);
    });

    it('decreases after an item is removed', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 1, 1);
      cart.removeItem('apple');
      assert.equal(cart.getItemCount(), 1);
    });

    it('does not change when an add is rejected', () => {
      cart.addItem('apple', 1, 1);
      assert.throws(() => cart.addItem('banana', -1, 1), RangeError);
      assert.equal(cart.getItemCount(), 1);
    });
  });
});
